        if (string.Equals(fieldId, "kind", StringComparison.Ordinal)) { field = Kind; return true; }
        if (string.Equals(fieldId, "skillId", StringComparison.Ordinal)) { field = SkillId; return true; }
        if (string.Equals(fieldId, "skillLevel", StringComparison.Ordinal)) { field = SkillLevel; return true; }
        if (string.Equals(fieldId, "comboSourceA", StringComparison.Ordinal)) { field = ComboSourceA; return true; }
        if (string.Equals(fieldId, "comboSourceB", StringComparison.Ordinal)) { field = ComboSourceB; return true; }
        if (string.Equals(fieldId, "comboLevelA", StringComparison.Ordinal)) { field = ComboLevelA; return true; }
        if (string.Equals(fieldId, "comboLevelB", StringComparison.Ordinal)) { field = ComboLevelB; return true; }
        if (string.Equals(fieldId, "droppedBy", StringComparison.Ordinal)) { field = DroppedBy; return true; }
        if (string.Equals(fieldId, "protectedUntilTick", StringComparison.Ordinal)) { field = ProtectedUntilTick; return true; }
        if (string.Equals(fieldId, "spawnTick", StringComparison.Ordinal)) { field = SpawnTick; return true; }
        if (string.Equals(fieldId, "phase", StringComparison.Ordinal)) { field = Phase; return true; }
        if (string.Equals(fieldId, "claimedBy", StringComparison.Ordinal)) { field = ClaimedBy; return true; }
        if (string.Equals(fieldId, "excludedLife", StringComparison.Ordinal)) { field = ExcludedLife; return true; }
        if (string.Equals(fieldId, "excludedLifeGeneration", StringComparison.Ordinal)) { field = ExcludedLifeGeneration; return true; }
        if (string.Equals(fieldId, "dropMatchId", StringComparison.Ordinal)) { field = DropMatchId; return true; }
        if (string.Equals(fieldId, "dropParticipant", StringComparison.Ordinal)) { field = DropParticipant; return true; }
        if (string.Equals(fieldId, "dropLifeGeneration", StringComparison.Ordinal)) { field = DropLifeGeneration; return true; }
        if (string.Equals(fieldId, "dropOccurrenceTick", StringComparison.Ordinal)) { field = DropOccurrenceTick; return true; }
        if (string.Equals(fieldId, "terrainTransaction", StringComparison.Ordinal)) { field = TerrainTransaction; return true; }
