    void IGeneratedComponent.ResetToDefault()
    {
        Kind.SetSilent(0);
        SkillId.SetSilent(0U);
        SkillLevel.SetSilent(0);
        ComboSourceA.SetSilent(0U);
        ComboSourceB.SetSilent(0U);
        ComboLevelA.SetSilent(0);
        ComboLevelB.SetSilent(0);
        DroppedBy.SetSilent(default!);
        ProtectedUntilTick.SetSilent(0UL);
        SpawnTick.SetSilent(0UL);
        Phase.SetSilent(0);
        ClaimedBy.SetSilent(default!);
        ExcludedLife.SetSilent(default!);
        ExcludedLifeGeneration.SetSilent(0UL);
        DropMatchId.SetSilent(0UL);
        DropParticipant.SetSilent(default!);
        DropLifeGeneration.SetSilent(0UL);
        DropOccurrenceTick.SetSilent(0UL);
        TerrainTransaction.SetSilent(string.Empty);
        TerrainSourceBomb.SetSilent(default!);
        TerrainSourceFamily.SetSilent(default!);
        TerrainOrdinal.SetSilent(0);
        SupplyMatchId.SetSilent(0UL);
        SupplyOrdinal.SetSilent(0);
    }
